metadata.ans:document:
{
  "format": "ariadne-nsd",
  "version": 1,
  "settings": {
    "textKind": "plain",
    "theme": "default",
    "headStyle": "title",
    "locale": "ko"
  },
  "diagrams": [
    {
      "id": "d1",
      "head": {
        "kind": "method",
        "text": "max_flow(cap, s, t)"
      },
      "body": [
        {
          "id": "b1",
          "kind": "process",
          "text": "flow = 0    # cap[u][v]: 남은 용량 (역방향 간선 포함)"
        },
        {
          "id": "b2",
          "kind": "endless",
          "body": [
            {
              "id": "b3",
              "kind": "call",
              "target": {
                "kind": "local",
                "diagram": "d2"
              },
              "args": "cap, s, t",
              "result": "parent"
            },
            {
              "id": "b4",
              "kind": "if",
              "text": "t not in parent",
              "yes": {
                "id": "r1",
                "body": [
                  {
                    "id": "b5",
                    "kind": "exit",
                    "text": "return flow    # 증가 경로가 없다"
                  }
                ]
              },
              "no": {
                "id": "r2",
                "body": [
                  {
                    "id": "b6",
                    "kind": "process",
                    "text": ""
                  }
                ]
              }
            },
            {
              "id": "b7",
              "kind": "process",
              "text": "b, v = INF, t"
            },
            {
              "id": "b8",
              "kind": "while",
              "text": "v != s",
              "body": [
                {
                  "id": "b9",
                  "kind": "process",
                  "text": "u = parent[v]"
                },
                {
                  "id": "b10",
                  "kind": "process",
                  "text": "b = min(b, cap[u][v])"
                },
                {
                  "id": "b11",
                  "kind": "process",
                  "text": "v = u"
                }
              ]
            },
            {
              "id": "b12",
              "kind": "process",
              "text": "v = t"
            },
            {
              "id": "b13",
              "kind": "while",
              "text": "v != s",
              "body": [
                {
                  "id": "b14",
                  "kind": "process",
                  "text": "u = parent[v]"
                },
                {
                  "id": "b15",
                  "kind": "process",
                  "text": "cap[u][v] -= b"
                },
                {
                  "id": "b16",
                  "kind": "process",
                  "text": "cap[v][u] += b    # 되돌릴 수 있게"
                },
                {
                  "id": "b17",
                  "kind": "process",
                  "text": "v = u"
                }
              ]
            },
            {
              "id": "b18",
              "kind": "process",
              "text": "flow += b"
            }
          ],
          "folds": [
            {
              "id": "f1",
              "first": "b7",
              "last": "b8",
              "name": "경로의 병목 찾기"
            },
            {
              "id": "f2",
              "first": "b12",
              "last": "b13",
              "name": "경로를 따라 흘려 보내기"
            }
          ]
        }
      ]
    },
    {
      "id": "d2",
      "head": {
        "kind": "method",
        "text": "bfs_path(cap, s, t)"
      },
      "body": [
        {
          "id": "b19",
          "kind": "process",
          "text": "parent = {s: s}    # 간선 수가 가장 적은 경로"
        },
        {
          "id": "b20",
          "kind": "process",
          "text": "q = deque([s])"
        },
        {
          "id": "b21",
          "kind": "while",
          "text": "q and t not in parent",
          "body": [
            {
              "id": "b22",
              "kind": "process",
              "text": "u = q.popleft()"
            },
            {
              "id": "b23",
              "kind": "for",
              "text": "for v in cap[u]",
              "body": [
                {
                  "id": "b24",
                  "kind": "if",
                  "text": "v not in parent and cap[u][v] > 0",
                  "yes": {
                    "id": "r3",
                    "body": [
                      {
                        "id": "b25",
                        "kind": "process",
                        "text": "parent[v] = u"
                      },
                      {
                        "id": "b26",
                        "kind": "process",
                        "text": "q.append(v)"
                      }
                    ]
                  },
                  "no": {
                    "id": "r4",
                    "body": [
                      {
                        "id": "b27",
                        "kind": "process",
                        "text": ""
                      }
                    ]
                  }
                }
              ]
            }
          ]
        },
        {
          "id": "b28",
          "kind": "process",
          "text": "return parent"
        }
      ]
    }
  ],
  "view": {
    "folded": [],
    "opened": [],
    "bands": true,
    "resultSymbol": "←"
  }
}
